		t.Error("a tree reports a line count, which is the text display's answer")
	}
}

func headerValue(t *testing.T, m Model, key string) string {
	t.Helper()
	for _, info := range m.GetHeaderInfo("default") {
		if info.Key == key {
			return info.Value
		}
	}
	return ""
}

